package com.aistock.market.marketreview;
import com.aistock.market.support.MarketDatabaseFixture;import com.aistock.common.BusinessException;import com.aistock.common.marketreview.MarketReviewContract.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class MarketReviewMysqlTest {
 JdbcTemplate j;MarketReviewService service;String v;String actor="00000000-0000-0000-0000-000000000001";Clock clock=Clock.fixed(Instant.parse("2026-10-28T02:00:00Z"),ZoneOffset.UTC);
 @BeforeEach void init(){j=new MarketDatabaseFixture().jdbc();j.update("insert into instrument(instrument_id,ticker,display_name,demo_only) values('SH600030','SH600030','test',false)");v=UUID.randomUUID().toString();j.update("insert into market_data_version(version_id,instrument_id,provider,price_basis,status,quality,content_hash,source_payload_hash,fetched_at,published_at,coverage_start,coverage_end) values(?,'SH600030','baostock','RAW','AVAILABLE','ROW_VALIDATED',?,?,now(),now(),'2026-01-01','2026-10-23')",v,"a".repeat(64),"b".repeat(64));service=new MarketReviewService(j,clock);}
 Command command(String rev){return new Command(UUID.randomUUID().toString(),rev,"REVIEWED","验收测试数据，核对来源与日期");}
 @Test void readsDoNotWriteAndSaveIsIdempotent(){var before=j.queryForList("select * from market_data_version");assertEquals("0",service.read("SH600030",v).revision());assertEquals(0,j.queryForObject("select count(*) from market_version_review",Integer.class));var c=command("0");var r=service.save("SH600030",v,actor,c);assertEquals("1",r.revision());assertEquals(r,service.save("SH600030",v,actor,c));var page=service.read("SH600030",v);assertEquals(r,page.current());assertEquals(List.of(r),page.history());assertEquals(r,service.operation("SH600030",v,actor,c.operationId()));assertEquals(before,j.queryForList("select * from market_data_version"));assertEquals(1,j.queryForObject("select count(*) from market_version_review_operation",Integer.class));}
 @Test void rejectsStaleAlteredActorAndWrongOwnership(){var c=command("0");service.save("SH600030",v,actor,c);assertEquals("REVIEW_REVISION_CONFLICT",assertThrows(BusinessException.class,()->service.save("SH600030",v,actor,command("0"))).code());assertEquals("REVIEW_OPERATION_CONFLICT",assertThrows(BusinessException.class,()->service.save("SH600030",v,actor,new Command(c.operationId(),"0","NEEDS_REVIEW","另一个说明"))).code());assertThrows(BusinessException.class,()->service.save("SH600030",v,"00000000-0000-0000-0000-000000000002",c));assertEquals(404,assertThrows(BusinessException.class,()->service.read("SH600276",v)).status().value());assertEquals(404,assertThrows(BusinessException.class,()->service.operation("SH600030",v,"00000000-0000-0000-0000-000000000002",c.operationId())).status().value());assertEquals("1",service.read("SH600030",v).revision());}
 @Test void preservesHistoryAndMarksProgressNotAvailability(){for(int n=0;n<22;n++)service.save("SH600030",v,actor,command(""+n));var page=service.read("SH600030",v);assertEquals("22",page.revision());assertEquals(20,page.history().size());assertTrue(page.hasMore());assertEquals("3",page.history().get(19).revision());assertEquals(22,j.queryForObject("select count(*) from market_version_review_operation",Integer.class));assertEquals("AVAILABLE",j.queryForObject("select status from market_data_version where version_id=?",String.class,v));}
 @Test void concurrentRevisionOnlyOneSucceeds()throws Exception{var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var futures=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++)futures.add(pool.submit(()->{start.await();try{service.save("SH600030",v,actor,command("0"));return true;}catch(BusinessException e){assertEquals("REVIEW_REVISION_CONFLICT",e.code());return false;}}));start.countDown();int success=0;for(var f:futures)if(f.get(10,TimeUnit.SECONDS))success++;assertEquals(1,success);assertEquals(1,j.queryForObject("select count(*) from market_version_review_operation",Integer.class));}finally{pool.shutdownNow();}}
}
